import { normalizeAssistantCacheContent } from '../utils/cache-normalize.js';
import { attachHandlersToToolCalls } from '../utils/tool-helpers.js';
export function aggregateEvents(events) {
    let contentText = '';
    let thinkingText = '';
    let stats;
    let rawFullText;
    let error;
    let stopReason;
    let cancelled = false;
    const toolCalls = [];
    for (const event of events) {
        if (event.type === 'contentDelta') {
            contentText += event.text;
        }
        else if (event.type === 'thinkingDelta') {
            thinkingText += event.text;
        }
        else if (event.type === 'completionStats') {
            stats = event.stats;
        }
        else if (event.type === 'toolCall') {
            toolCalls.push(event.call);
        }
        else if (event.type === 'completionDone') {
            if ('raw' in event && event.raw) {
                rawFullText = event.raw.fullText;
            }
            // Error wins over cancelled if a wire event ever carries both
            // signals: a mid-stream addon failure makes the partial state
            // unsafe to expose, regardless of why the loop exited.
            if (event.stopReason === 'error' && 'error' in event) {
                error = event.error;
            }
            else {
                if (event.stopReason !== undefined) {
                    stopReason = event.stopReason;
                }
                if (event.stopReason === 'cancelled') {
                    cancelled = true;
                }
            }
        }
    }
    return {
        contentText,
        thinkingText,
        stats,
        toolCalls,
        rawFullText,
        error,
        stopReason,
        cancelled
    };
}
export function buildFinalFromEvents(events, handlers) {
    const { contentText, thinkingText, stats, toolCalls, rawFullText, error, stopReason, cancelled } = aggregateEvents(events);
    const attachedToolCalls = attachHandlersToToolCalls(toolCalls, handlers);
    const fullText = rawFullText ?? contentText;
    const cacheableAssistantContent = attachedToolCalls.length === 0 ? normalizeAssistantCacheContent(fullText) : undefined;
    const final = {
        contentText,
        ...(thinkingText && { thinkingText }),
        toolCalls: attachedToolCalls,
        ...(stats && { stats }),
        raw: { fullText },
        ...(cacheableAssistantContent !== undefined && {
            cacheableAssistantContent
        }),
        ...(stopReason !== undefined && { stopReason })
    };
    return { final, error, cancelled };
}
